-- Generated by generate-branch-schema.js from the desktop schema and migrations. Do not edit.
-- One copy of this schema exists per branch (schema branch_<id>); compat holds the SQLite
-- functions the shared handlers use.

CREATE TABLE accounts (
  id SERIAL PRIMARY KEY,
  name TEXT COLLATE "C" NOT NULL,
  type TEXT COLLATE "C" NOT NULL CHECK(type IN ('CASH', 'BANK')),
  account_number TEXT COLLATE "C",
  initial_balance DOUBLE PRECISION DEFAULT 0.0,
  current_balance DOUBLE PRECISION DEFAULT 0.0,
  is_active INTEGER DEFAULT 1,
  created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now()
);

CREATE TABLE age_groups (
    id SERIAL PRIMARY KEY,
    uuid TEXT COLLATE "C" UNIQUE NOT NULL,
    name TEXT COLLATE "C" NOT NULL,
    description TEXT COLLATE "C",
    min_age INTEGER NOT NULL CHECK(min_age >= 0),
    max_age INTEGER NULL CHECK(max_age IS NULL OR max_age >= min_age),
    gender TEXT COLLATE "C" NOT NULL CHECK(gender IN ('male_only', 'female_only', 'any')),
    gender_policy TEXT COLLATE "C" DEFAULT 'mixed' CHECK(gender_policy IN ('mixed', 'separated', 'single_gender')),
    is_active INTEGER DEFAULT 1,
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    updated_at TEXT COLLATE "C" DEFAULT compat.sqlite_now()
  , payment_frequency TEXT COLLATE "C" NOT NULL DEFAULT 'MONTHLY'
  CHECK (payment_frequency IN ('MONTHLY', 'ANNUAL')), annual_fee DOUBLE PRECISION CHECK (annual_fee IS NULL OR annual_fee >= 0), monthly_fee DOUBLE PRECISION CHECK (monthly_fee IS NULL OR monthly_fee >= 0));

CREATE TABLE students (
    id SERIAL PRIMARY KEY,
    matricule TEXT COLLATE "C" UNIQUE,
    name TEXT COLLATE "C" NOT NULL,
    date_of_birth TEXT COLLATE "C",
    gender TEXT COLLATE "C",
    address TEXT COLLATE "C",
    contact_info TEXT COLLATE "C",
    email TEXT COLLATE "C",
    enrollment_date TEXT COLLATE "C" DEFAULT compat.sqlite_today(),
    status TEXT COLLATE "C" DEFAULT 'active',
    notes TEXT COLLATE "C",
    parent_name TEXT COLLATE "C",
    guardian_relation TEXT COLLATE "C",
    parent_contact TEXT COLLATE "C",
    guardian_email TEXT COLLATE "C",
    emergency_contact_name TEXT COLLATE "C",
    emergency_contact_phone TEXT COLLATE "C",
    health_conditions TEXT COLLATE "C",
    national_id TEXT COLLATE "C",
    school_name TEXT COLLATE "C",
    grade_level TEXT COLLATE "C",
    educational_level TEXT COLLATE "C",
    occupation TEXT COLLATE "C",
    civil_status TEXT COLLATE "C",
    related_family_members TEXT COLLATE "C",
    financial_assistance_notes TEXT COLLATE "C",
    is_full_memorizer INTEGER DEFAULT 0
, fee_category TEXT COLLATE "C" DEFAULT 'CAN_PAY' CHECK (fee_category IN ('CAN_PAY', 'EXEMPT', 'SPONSORED')), sponsor_name TEXT COLLATE "C", sponsor_phone TEXT COLLATE "C", sponsor_cin TEXT COLLATE "C", discount_percentage DOUBLE PRECISION DEFAULT 0 
  CHECK(discount_percentage >= 0 AND discount_percentage <= 100), discount_reason TEXT COLLATE "C", fee_age_group_id INTEGER REFERENCES age_groups(id) ON DELETE SET NULL, deleted_at TEXT COLLATE "C", deleted_by INTEGER);

CREATE TABLE branches (
    id SERIAL PRIMARY KEY,
    name TEXT COLLATE "C" UNIQUE NOT NULL,
    location TEXT COLLATE "C",
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now()
  );

CREATE TABLE teachers (
    id SERIAL PRIMARY KEY,
    name TEXT COLLATE "C" NOT NULL,
    national_id TEXT COLLATE "C",
    contact_info TEXT COLLATE "C",
    email TEXT COLLATE "C",
    address TEXT COLLATE "C",
    date_of_birth TEXT COLLATE "C",
    gender TEXT COLLATE "C",
    educational_level TEXT COLLATE "C",
    specialization TEXT COLLATE "C",
    years_of_experience INTEGER,
    availability TEXT COLLATE "C",
    notes TEXT COLLATE "C",
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    branch_id INTEGER, matricule TEXT COLLATE "C", deleted_at TEXT COLLATE "C", deleted_by INTEGER,
    FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE SET NULL
  );

CREATE TABLE classes (
    id SERIAL PRIMARY KEY,
    name TEXT COLLATE "C" NOT NULL,
    class_type TEXT COLLATE "C",
    teacher_id INTEGER,
    schedule TEXT COLLATE "C", 
    start_date TEXT COLLATE "C",
    end_date TEXT COLLATE "C",
    status TEXT COLLATE "C" DEFAULT 'pending', 
    capacity INTEGER,
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    gender TEXT COLLATE "C" CHECK(gender IN ('women', 'men', 'kids', 'all')) DEFAULT 'all',
    age_group_id INTEGER, fee_type TEXT COLLATE "C" DEFAULT 'standard' CHECK(fee_type IN ('standard', 'special')), monthly_fee DOUBLE PRECISION DEFAULT 0, deleted_at TEXT COLLATE "C", deleted_by INTEGER,
    FOREIGN KEY (teacher_id) REFERENCES teachers(id) ON DELETE SET NULL,
    FOREIGN KEY (age_group_id) REFERENCES age_groups(id) ON DELETE RESTRICT
  );

CREATE TABLE attendance (
    student_id INTEGER NOT NULL,
    class_id INTEGER NOT NULL,
    date TEXT COLLATE "C" NOT NULL, 
    status TEXT COLLATE "C" NOT NULL CHECK(status IN ('present', 'absent', 'late')),
    PRIMARY KEY (class_id, student_id, date),
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE CASCADE
  );

CREATE TABLE categories (
  id SERIAL PRIMARY KEY,
  name TEXT COLLATE "C" NOT NULL UNIQUE,
  type TEXT COLLATE "C" NOT NULL CHECK(type IN ('INCOME', 'EXPENSE')),
  description TEXT COLLATE "C",
  is_active INTEGER DEFAULT 1
);

CREATE TABLE class_students (
    class_id INTEGER NOT NULL,
    student_id INTEGER NOT NULL,
    enrollment_date TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    PRIMARY KEY (class_id, student_id),
    FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE CASCADE,
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
  );

CREATE TABLE receipt_books (
    id SERIAL PRIMARY KEY,
    book_number TEXT COLLATE "C" UNIQUE NOT NULL,
    start_receipt_number INTEGER NOT NULL,
    end_receipt_number INTEGER NOT NULL,
    current_receipt_number INTEGER NOT NULL,
    receipt_type TEXT COLLATE "C" NOT NULL CHECK(receipt_type IN ('payment', 'donation', 'expense', 'salary', 'fee_payment')),
    status TEXT COLLATE "C" NOT NULL DEFAULT 'active' CHECK(status IN ('active', 'completed', 'cancelled')),
    issued_date TEXT COLLATE "C" NOT NULL,
    notes TEXT COLLATE "C",
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    updated_at TEXT COLLATE "C" DEFAULT compat.sqlite_now()
, deleted_at TEXT COLLATE "C", deleted_by INTEGER);

CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username TEXT COLLATE "C" UNIQUE NOT NULL,
    password TEXT COLLATE "C" NOT NULL,
    first_name TEXT COLLATE "C",
    last_name TEXT COLLATE "C",
    date_of_birth TEXT COLLATE "C",
    national_id TEXT COLLATE "C" UNIQUE,
    email TEXT COLLATE "C" UNIQUE,
    phone_number TEXT COLLATE "C",
    occupation TEXT COLLATE "C",
    civil_status TEXT COLLATE "C" CHECK(civil_status IN ('Single', 'Married', 'Divorced', 'Widowed')),
    employment_type TEXT COLLATE "C" CHECK(employment_type IN ('volunteer', 'contract')),
    start_date TEXT COLLATE "C",
    end_date TEXT COLLATE "C",
    status TEXT COLLATE "C" NOT NULL DEFAULT 'active' CHECK(status IN ('active', 'inactive')),
    notes TEXT COLLATE "C",
    need_guide INTEGER DEFAULT 1,
    current_step INTEGER DEFAULT 0,
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    branch_id INTEGER, matricule TEXT COLLATE "C", deleted_at TEXT COLLATE "C", deleted_by INTEGER,
    FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE SET NULL
  );

CREATE TABLE donations (
    id SERIAL PRIMARY KEY,
    donor_name TEXT COLLATE "C" NOT NULL,
    amount DOUBLE PRECISION,
    donation_date TEXT COLLATE "C" NOT NULL,
    donation_type TEXT COLLATE "C" NOT NULL DEFAULT 'Cash',
    description TEXT COLLATE "C",
    notes TEXT COLLATE "C",
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    updated_at TEXT COLLATE "C" DEFAULT compat.sqlite_now()
  , quantity INTEGER, category TEXT COLLATE "C", receipt_number TEXT COLLATE "C", receipt_book_id INTEGER REFERENCES receipt_books(id), receipt_issued_by INTEGER REFERENCES users(id), receipt_issued_date TEXT COLLATE "C");

CREATE TABLE expenses (
    id SERIAL PRIMARY KEY,
    category TEXT COLLATE "C" NOT NULL,
    amount DOUBLE PRECISION NOT NULL,
    expense_date TEXT COLLATE "C" NOT NULL,
    responsible_person TEXT COLLATE "C",
    description TEXT COLLATE "C",
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    updated_at TEXT COLLATE "C" DEFAULT compat.sqlite_now()
  , receipt_number TEXT COLLATE "C", receipt_book_id INTEGER REFERENCES receipt_books(id), receipt_issued_by INTEGER REFERENCES users(id), receipt_issued_date TEXT COLLATE "C");

CREATE TABLE groups (
    id SERIAL PRIMARY KEY,
    name TEXT COLLATE "C" NOT NULL UNIQUE,
    description TEXT COLLATE "C",
    category TEXT COLLATE "C" NOT NULL,
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    updated_at TEXT COLLATE "C" DEFAULT compat.sqlite_now()
  , matricule TEXT COLLATE "C", deleted_at TEXT COLLATE "C", deleted_by INTEGER);

CREATE TABLE hizbs (
    id INTEGER PRIMARY KEY,
    hizb_number INTEGER NOT NULL UNIQUE
);

CREATE TABLE in_kind_categories (
  id SERIAL PRIMARY KEY,
  name TEXT COLLATE "C" NOT NULL UNIQUE,
  is_system INTEGER DEFAULT 0,
  is_active INTEGER DEFAULT 1
, deleted_at TEXT COLLATE "C", deleted_by INTEGER);

CREATE TABLE inventory_items (
  id SERIAL PRIMARY KEY,
  matricule TEXT COLLATE "C" UNIQUE NOT NULL,
  item_name TEXT COLLATE "C" NOT NULL,
  category TEXT COLLATE "C" NOT NULL,
  quantity INTEGER NOT NULL DEFAULT 0,
  unit_value DOUBLE PRECISION,
  total_value DOUBLE PRECISION,
  acquisition_date TEXT COLLATE "C",
  acquisition_source TEXT COLLATE "C",
  condition_status TEXT COLLATE "C",
  location TEXT COLLATE "C",
  notes TEXT COLLATE "C",
  created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
  updated_at TEXT COLLATE "C" DEFAULT compat.sqlite_now()
, deleted_at TEXT COLLATE "C", deleted_by INTEGER);

CREATE TABLE migrations (
    id SERIAL PRIMARY KEY,
    name TEXT COLLATE "C" UNIQUE NOT NULL,
    applied_at TEXT COLLATE "C" DEFAULT compat.sqlite_now()
  );

CREATE TABLE payments (
    id SERIAL PRIMARY KEY,
    student_id INTEGER NOT NULL,
    amount DOUBLE PRECISION NOT NULL,
    payment_date TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    payment_method TEXT COLLATE "C",
    notes TEXT COLLATE "C",
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    updated_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(), receipt_number TEXT COLLATE "C", receipt_book_id INTEGER REFERENCES receipt_books(id), receipt_issued_by INTEGER REFERENCES users(id), receipt_issued_date TEXT COLLATE "C",
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
  );

CREATE TABLE roles (
    id SERIAL PRIMARY KEY,
    name TEXT COLLATE "C" UNIQUE NOT NULL
  );

CREATE TABLE salaries (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    user_type TEXT COLLATE "C" NOT NULL,
    amount DOUBLE PRECISION NOT NULL,
    payment_date TEXT COLLATE "C" NOT NULL,
    notes TEXT COLLATE "C",
    created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    updated_at TEXT COLLATE "C" DEFAULT compat.sqlite_now()
  , receipt_number TEXT COLLATE "C", receipt_book_id INTEGER REFERENCES receipt_books(id), receipt_issued_by INTEGER REFERENCES users(id), receipt_issued_date TEXT COLLATE "C");

CREATE TABLE settings (
    key TEXT COLLATE "C" PRIMARY KEY NOT NULL,
    value TEXT COLLATE "C"
  );

CREATE TABLE student_fee_charges (
  id SERIAL PRIMARY KEY,
  student_id INTEGER NOT NULL,
  charge_date TEXT COLLATE "C" NOT NULL,
  due_date TEXT COLLATE "C",
  fee_type TEXT COLLATE "C" NOT NULL, 
  description TEXT COLLATE "C",
  amount DOUBLE PRECISION NOT NULL,
  amount_paid DOUBLE PRECISION DEFAULT 0,
  status TEXT COLLATE "C" DEFAULT 'UNPAID' CHECK(status IN ('UNPAID', 'PARTIALLY_PAID', 'PAID')),
  academic_year TEXT COLLATE "C",
  related_class_id INTEGER,
  created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(), payment_frequency TEXT COLLATE "C" DEFAULT 'MONTHLY' CHECK (payment_frequency IN ('MONTHLY', 'ANNUAL')), billing_month TEXT COLLATE "C", source_payment_id INTEGER, cancelled_at TEXT COLLATE "C",
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (related_class_id) REFERENCES classes(id) ON DELETE CASCADE
);

CREATE TABLE student_groups (
    id SERIAL PRIMARY KEY,
    student_id INTEGER NOT NULL,
    group_id INTEGER NOT NULL,
    joined_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    FOREIGN KEY (group_id) REFERENCES groups(id) ON DELETE CASCADE,
    UNIQUE(student_id, group_id)
  );

CREATE TABLE student_hizbs (
    student_id INTEGER NOT NULL,
    hizb_id INTEGER NOT NULL,
    PRIMARY KEY (student_id, hizb_id),
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    FOREIGN KEY (hizb_id) REFERENCES hizbs(id) ON DELETE CASCADE
);

CREATE TABLE transactions (
  id SERIAL PRIMARY KEY,
  transaction_date TEXT COLLATE "C" NOT NULL,
  type TEXT COLLATE "C" NOT NULL CHECK(type IN ('INCOME', 'EXPENSE')),
  category TEXT COLLATE "C" NOT NULL,
  amount DOUBLE PRECISION NOT NULL,
  description TEXT COLLATE "C",
  payment_method TEXT COLLATE "C" CHECK(payment_method IN ('CASH', 'CHECK', 'TRANSFER')),
  check_number TEXT COLLATE "C",
  voucher_number TEXT COLLATE "C",
  related_entity_type TEXT COLLATE "C",
  related_entity_id INTEGER,
  related_person_name TEXT COLLATE "C",
  account_id INTEGER NOT NULL,
  requires_dual_signature INTEGER DEFAULT 0,
  receipt_type TEXT COLLATE "C",
  created_by_user_id INTEGER,
  created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
  updated_at TEXT COLLATE "C",
  matricule TEXT COLLATE "C",
  receipt_number TEXT COLLATE "C",
  voided_at TEXT COLLATE "C",
  voided_by INTEGER
);

CREATE TABLE student_payments (
  id SERIAL PRIMARY KEY,
  student_id INTEGER NOT NULL,
  amount DOUBLE PRECISION NOT NULL,
  payment_date TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
  payment_method TEXT COLLATE "C",
  payment_type TEXT COLLATE "C",
  academic_year TEXT COLLATE "C",
  notes TEXT COLLATE "C",
  check_number TEXT COLLATE "C",
  receipt_number TEXT COLLATE "C",
  class_id TEXT COLLATE "C", 
  transaction_id INTEGER,
  created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
  updated_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(), sponsor_name TEXT COLLATE "C", sponsor_phone TEXT COLLATE "C", refunded INTEGER NOT NULL DEFAULT 0, voided_at TEXT COLLATE "C", voided_by INTEGER,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (transaction_id) REFERENCES transactions(id) ON DELETE SET NULL
);

CREATE TABLE student_payment_breakdown (
  id SERIAL PRIMARY KEY,
  student_payment_id INTEGER NOT NULL,
  student_fee_charge_id INTEGER NOT NULL,
  amount DOUBLE PRECISION NOT NULL,
  created_at TEXT COLLATE "C" DEFAULT compat.sqlite_now(),
  FOREIGN KEY (student_payment_id) REFERENCES student_payments(id) ON DELETE CASCADE,
  FOREIGN KEY (student_fee_charge_id) REFERENCES student_fee_charges(id) ON DELETE CASCADE
);

CREATE TABLE surahs (
    id INTEGER PRIMARY KEY,
    name_ar TEXT COLLATE "C" NOT NULL,
    name_en TEXT COLLATE "C" NOT NULL,
    revelation_type TEXT COLLATE "C" CHECK(revelation_type IN ('Meccan', 'Medinan')),
    verse_count INTEGER NOT NULL
);

CREATE TABLE student_surahs (
    student_id INTEGER NOT NULL,
    surah_id INTEGER NOT NULL,
    PRIMARY KEY (student_id, surah_id),
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    FOREIGN KEY (surah_id) REFERENCES surahs(id) ON DELETE CASCADE
);

CREATE TABLE user_roles (
    user_id INTEGER NOT NULL,
    role_id INTEGER NOT NULL,
    PRIMARY KEY (user_id, role_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE
  );

CREATE INDEX idx_donations_receipt ON donations(receipt_number);
CREATE INDEX idx_expenses_receipt ON expenses(receipt_number);
CREATE UNIQUE INDEX idx_groups_matricule ON groups(matricule);
CREATE INDEX idx_payments_receipt ON payments(receipt_number);
CREATE INDEX idx_receipt_books_status ON receipt_books(status);
CREATE INDEX idx_salaries_receipt ON salaries(receipt_number);
CREATE INDEX idx_student_fee_charges_billing_month ON student_fee_charges(student_id, billing_month);
CREATE UNIQUE INDEX idx_teachers_matricule ON teachers(matricule);
CREATE UNIQUE INDEX idx_transactions_matricule ON transactions(matricule);
CREATE UNIQUE INDEX idx_transactions_voucher_active ON transactions(voucher_number, type) WHERE voided_at IS NULL;
CREATE UNIQUE INDEX idx_users_matricule ON users(matricule);

